import { Component, effect, input, signal } from '@angular/core';

@Component({
  selector: 'app-product-search',
  template: `
    <input #box (input)="query.set(box.value)" />
    @for (p of matches(); track p.id) { <p>{{ p.name }}</p> }
  `,
})
export class ProductSearch {
  readonly products = input.required<Product[]>();
  readonly query = signal('');
  readonly matches = signal<Product[]>([]);

  constructor() {
    // A copy, refreshed later, during change detection
    effect(() => {
      this.matches.set(this.products().filter(byName(this.query())));
    });
  }
}

import { Component, computed, input, signal } from '@angular/core';

@Component({
  selector: 'app-product-search',
  template: `
    <input #box (input)="query.set(box.value)" />
    @for (p of matches(); track p.id) { <p>{{ p.name }}</p> }
  `,
})
export class ProductSearch {
  readonly products = input.required<Product[]>();
  readonly query = signal('');

  // Derived when read, so it's current right after query.set()
  readonly matches = computed(() =>
    this.products().filter(byName(this.query())),
  );
}

