import { Component, input, linkedSignal } from '@angular/core';

@Component({
  selector: 'app-product-picker',
  templateUrl: './product-picker.html', // buttons call selected.set(p)
})
export class ProductPicker {
  readonly matches = input.required<Product[]>();

  // The user's pick while it's still listed, else the first match
  readonly selected = linkedSignal<Product[], Product | undefined>({
    source: this.matches,
    computation: (list, previous) =>
      list.find((p) => p.id === previous?.value?.id) ?? list[0],
  });
}
